import React,{useState} from 'react';
import Header from '../components/Header';
import Footer from '../components/Footer';

const style=`
*{box-sizing:border-box}
.courses-page{width:100%;margin:0;padding:0;color:#153c43;font-family:Inter,Arial,sans-serif;background:#fff;overflow:hidden}
.courses-page button{font-family:inherit}
.courses-hero{min-height:460px;position:relative;display:flex;align-items:center;background:linear-gradient(90deg,#034f51 0%,#075d5d 42%,rgba(5,75,76,.6) 65%,rgba(5,75,76,.25) 100%),url("https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1800&q=90") center/cover no-repeat}
.courses-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(1,58,59,.95) 0%,rgba(1,58,59,.82) 40%,rgba(1,58,59,.1) 75%,rgba(1,58,59,.15) 100%)}
.courses-hero-inner{width:min(1180px,calc(100% - 48px));margin:auto;position:relative;z-index:2}
.hero-copy{width:53%;padding:55px 0}
.hero-small{color:#fff;font-size:12px;letter-spacing:3px;font-weight:800;margin-bottom:12px}
.hero-heading{font-family:Georgia,"Times New Roman",serif;font-size:56px;line-height:.98;margin:0;color:#fff;letter-spacing:-1px}
.hero-heading span{color:#edbd50}
.hero-desc{color:#fff;font-size:15px;line-height:1.55;max-width:570px;margin:17px 0 25px}
.hero-features{display:grid;grid-template-columns:repeat(4,1fr);max-width:500px}
.hero-feature{border-right:1px solid rgba(255,255,255,.35);padding:4px 20px 3px 5px;color:#fff}
.hero-feature:last-child{border-right:0}
.hero-feature-icon{font-size:27px;height:35px;display:flex;align-items:center}
.hero-feature-text{font-size:12px;line-height:1.35;font-weight:600}
.hero-side-text{position:absolute;right:15px;top:35px;color:#fff;font-family:"Comic Sans MS",cursive;font-size:25px;line-height:1.08;font-style:italic;transform:rotate(-5deg);text-align:center}
.hero-side-text:after{content:"";display:block;width:65px;height:3px;background:#efbf4e;transform:rotate(-10deg);margin:8px auto}
.hero-heart{color:#efbf4e;font-size:31px}
.explore-section{padding:26px 0 35px;background:#fff}
.section-container{width:min(1180px,calc(100% - 48px));margin:auto}
.explore-heading{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:18px}
.explore-label{font-size:11px;font-weight:800;letter-spacing:3px;color:#075d60;margin-bottom:7px}
.explore-title{font-family:Georgia,"Times New Roman",serif;font-size:43px;line-height:1.08;margin:0;color:#103c43}
.explore-title span{color:#bd8b25}
.learning-note{font-family:"Comic Sans MS",cursive;color:#174d52;font-size:20px;line-height:1.05;text-align:center;transform:rotate(-6deg);margin-right:15px}
.learning-note:after{content:"";display:block;width:65px;height:3px;background:#c79427;margin:7px auto;transform:rotate(-7deg)}
.course-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
.course-card{position:relative;min-height:390px;border:1px solid #e1edeb;border-radius:11px;padding:13px 16px 13px;background:linear-gradient(145deg,#f4fbf9,#edf7f5);display:flex;flex-direction:column;transition:.25s ease}
.course-card:hover{transform:translateY(-4px);box-shadow:0 12px 25px rgba(4,77,78,.11)}
.course-badge{position:absolute;right:9px;top:10px;padding:5px 11px;border-radius:14px;background:#08706d;color:#fff;font-size:10px;font-weight:800}
.course-badge.new{background:#efbe4b;color:#163c42}
.course-logo{height:82px;display:flex;align-items:center;justify-content:center;font-size:58px;letter-spacing:-10px}
.course-logo.java{color:#e84c28}
.course-logo.python{color:#2479bd;letter-spacing:0}
.course-logo.full{font-size:48px;letter-spacing:-7px}
.course-logo.mern{font-size:40px;letter-spacing:-5px}
.course-logo.data{color:#0766d2;font-size:57px;letter-spacing:0}
.course-logo.ai{font-size:58px;color:#164e51;letter-spacing:0}
.course-title{font-family:Georgia,"Times New Roman",serif;color:#113c43;font-size:19px;line-height:1.1;margin:3px 0 7px;font-weight:700}
.course-description{color:#53646a;font-size:12.5px;line-height:1.42;min-height:52px;margin:0 0 8px}
.course-topics{padding:0;margin:0;list-style:none}
.course-topics li{color:#596b70;font-size:11.5px;line-height:1.62;position:relative;padding-left:23px}
.course-topics li:before{content:"✓";position:absolute;left:0;top:2px;width:15px;height:15px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:#08736e;color:#fff;font-size:9px;font-weight:900}
.course-duration{margin-top:auto;padding-top:8px;color:#173e44;font-size:12px;font-weight:800;display:flex;align-items:center;gap:8px}
.clock{color:#c79527;font-size:18px}
.details-btn{width:100%;border:0;border-radius:23px;background:#075d5d;color:#fff;height:39px;margin-top:9px;font-size:12px;font-weight:800;cursor:pointer;transition:.25s}
.details-btn:hover{background:#043f41;transform:translateY(-1px)}
.promo-card{position:relative;min-height:390px;border-radius:11px;overflow:hidden;background:#075b5b}
.promo-card img{position:absolute;width:100%;height:100%;inset:0;object-fit:cover}
.promo-card:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(2,62,64,.1),rgba(2,62,64,.25))}
.promo-writing{position:absolute;z-index:2;right:15px;top:23px;color:#fff;font-family:"Comic Sans MS",cursive;font-size:25px;line-height:1.08;font-style:italic;transform:rotate(-5deg);text-align:center}
.promo-writing:after{content:"";display:block;width:72px;height:3px;background:#efc04e;margin:9px auto;transform:rotate(-8deg)}
.promo-books{position:absolute;z-index:3;bottom:18px;left:16%;width:68%}
.promo-book{height:27px;margin-top:2px;border-radius:3px;color:#f0c34d;background:linear-gradient(180deg,#193f40,#092f31);display:flex;align-items:center;justify-content:center;font-family:Georgia,serif;font-size:11px;font-weight:800;box-shadow:0 3px 5px rgba(0,0,0,.25)}
.benefits-section{padding:0 0 35px;background:#fff}
.benefits-bar{width:min(1180px,calc(100% - 48px));margin:auto;border:1px solid #dcebea;border-radius:38px;min-height:72px;padding:8px 14px;display:flex;align-items:center;box-shadow:0 6px 20px rgba(0,75,77,.06);background:rgba(255,255,255,.96)}
.benefits{flex:1;display:grid;grid-template-columns:repeat(4,1fr)}
.benefit{display:flex;align-items:center;gap:10px;padding:3px 14px;border-right:1px solid #d4e1df}
.benefit:last-child{border-right:0}
.benefit-icon{font-size:27px;color:#075e60}
.benefit-text{font-size:11px;line-height:1.3;color:#29454a}
.start-btn{border:0;background:#f0c354;color:#173d42;border-radius:25px;height:47px;padding:0 21px;font-size:12px;font-weight:800;white-space:nowrap;cursor:pointer}
.modal-backdrop{position:fixed;z-index:9999;inset:0;background:rgba(4,31,34,.72);display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(5px)}
.course-modal{width:min(720px,100%);max-height:90vh;overflow-y:auto;border-radius:18px;background:#fff;box-shadow:0 25px 70px rgba(0,0,0,.3);animation:modalIn .25s ease}
@keyframes modalIn{from{opacity:0;transform:translateY(20px) scale(.97)}to{opacity:1;transform:translateY(0) scale(1)}}
.modal-header{padding:23px 25px 18px;background:linear-gradient(135deg,#075d5d,#0b7370);color:#fff;display:flex;justify-content:space-between;gap:20px;align-items:flex-start}
.modal-title{font-family:Georgia,"Times New Roman",serif;font-size:29px;margin:0 0 7px}
.modal-description{font-size:13px;line-height:1.5;margin:0;color:#e7f5f3}
.close-btn{width:35px;height:35px;flex-shrink:0;border:0;border-radius:50%;background:rgba(255,255,255,.16);color:#fff;font-size:24px;cursor:pointer}
.modal-body{padding:23px 25px}
.modal-section-title{font-size:15px;color:#075d5d;font-weight:800;margin:0 0 10px}
.modal-topic-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:22px}
.modal-topic{padding:10px 12px;background:#f0f8f6;border-radius:8px;color:#4c6267;font-size:12px}
.modal-topic:before{content:"✓";color:#08736e;font-weight:900;margin-right:8px}
.modal-info-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.modal-info{border:1px solid #dce9e7;border-radius:10px;padding:13px;background:#fff}
.modal-info-label{font-size:10px;color:#718084;text-transform:uppercase;letter-spacing:1px}
.modal-info-value{font-size:13px;color:#173e44;font-weight:800;margin-top:4px}
.modal-footer{padding:15px 25px 22px;display:flex;gap:10px}
.modal-enquire{flex:1;border:0;background:#075d5d;color:#fff;height:43px;border-radius:22px;font-size:12px;font-weight:800;cursor:pointer}
.modal-close-bottom{border:1px solid #d4a63b;background:#fff;color:#23474c;height:43px;border-radius:22px;padding:0 22px;font-size:12px;font-weight:800;cursor:pointer}
@media(max-width:1050px){.hero-copy{width:60%}.hero-heading{font-size:48px}.course-grid{grid-template-columns:repeat(2,1fr)}.promo-card{min-height:390px}.benefits-bar{border-radius:20px;flex-direction:column;padding:12px}.benefits{width:100%}.start-btn{width:100%;margin-top:10px}}
@media(max-width:700px){.courses-hero{min-height:600px}.courses-hero-inner{width:calc(100% - 30px)}.hero-copy{width:100%;padding:45px 0 25px}.hero-heading{font-size:43px}.hero-desc{font-size:14px}.hero-features{grid-template-columns:repeat(2,1fr);gap:12px}.hero-feature{border-right:0;border-bottom:1px solid rgba(255,255,255,.3);padding:6px 10px 10px 0}.hero-side-text{display:none}.section-container{width:calc(100% - 30px)}.explore-heading{display:block}.explore-title{font-size:34px}.learning-note{display:none}.course-grid{grid-template-columns:1fr}.course-card,.promo-card{min-height:370px}.benefits{grid-template-columns:1fr 1fr;gap:8px}.benefit{border-right:0;padding:7px}.modal-topic-grid{grid-template-columns:1fr}.modal-info-grid{grid-template-columns:1fr}.modal-footer{flex-direction:column}.modal-close-bottom,.modal-enquire{width:100%}}
@media(max-width:420px){.hero-heading{font-size:38px}.hero-features{grid-template-columns:1fr 1fr}.benefits{grid-template-columns:1fr}.course-title{font-size:20px}}
`;

