const CourseCard=({course,onDetails})=>(
<article className="course-card">
{course.badge&&<span className={'course-badge '+(course.badge==='New'?'new':'')}>{course.badge}</span>}
<div className={'course-logo '+course.logoClass}>{course.logo}</div>
<h3 className="course-title">{course.title}</h3>
<p className="course-description">{course.description}</p>
<ul className="course-topics">{course.topics.map((topic,i)=><li key={i}>{topic}</li>)}</ul>
<div className="course-duration"><span className="clock">◷</span>{course.duration}</div>
<button className="details-btn" onClick={()=>onDetails(course)}>View Details&nbsp;&nbsp; →</button>
</article>
);

const CourseModal=({course,onClose})=>{
React.useEffect(()=>{const fn=e=>{if(e.key==='Escape')onClose()};document.addEventListener('keydown',fn);document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',fn);document.body.style.overflow=''}},[onClose]);
return(
<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}>
<div className="course-modal">
<div className="modal-header">
<div><h2 className="modal-title">{course.title}</h2><p className="modal-description">{course.overview}</p></div>
<button className="close-btn" onClick={onClose}>×</button>
</div>
<div className="modal-body">
<h3 className="modal-section-title">Course Curriculum</h3>
<div className="modal-topic-grid">{course.modules.map((module,i)=><div className="modal-topic" key={i}>{module}</div>)}</div>
<div className="modal-info-grid">
<div className="modal-info"><div className="modal-info-label">Duration</div><div className="modal-info-value">{course.duration}</div></div>
<div className="modal-info"><div className="modal-info-label">Level</div><div className="modal-info-value">{course.level}</div></div>
<div className="modal-info"><div className="modal-info-label">Training Mode</div><div className="modal-info-value">{course.mode}</div></div>
</div>
</div>
<div className="modal-footer">
<button className="modal-enquire" onClick={()=>alert(`Thank you for your interest in ${course.title}. Our team will contact you soon.`)}>Enquire About This Course →</button>
<button className="modal-close-bottom" onClick={onClose}>Close</button>
</div>
</div>
</div>
)};

